import json, urllib.request, time

def login():
    d = json.dumps({"username": "admin", "password": "admin123"}).encode()
    r = urllib.request.Request("http://localhost:3001/api/admin/login", data=d, headers={"Content-Type": "application/json"}, method="POST")
    return json.loads(urllib.request.urlopen(r, timeout=5).read()).get("token")

def update(token, pid, payload):
    d = json.dumps(payload).encode("utf-8")
    r = urllib.request.Request(f"http://localhost:3001/api/admin/products/{pid}", data=d, headers={"Content-Type": "application/json", "Authorization": f"Bearer {token}"}, method="PUT")
    return json.loads(urllib.request.urlopen(r, timeout=10).read())

def verify(token, pid):
    time.sleep(0.3)
    r = urllib.request.Request(f"http://localhost:3001/api/admin/products/{pid}", headers={"Authorization": f"Bearer {token}"})
    p = json.loads(urllib.request.urlopen(r, timeout=5).read())
    s = p.get('specifications_en', '{}')
    if isinstance(s, str): s = json.loads(s)
    a = p.get('applications_en', '[]')
    if isinstance(a, str): a = json.loads(a)
    print(f"  ID={pid} | {p.get('name_zh','')} | desc={len(p.get('description_en',''))} specs={len(s)} apps={len(a)}")

token = login()

